from taf.ul.kpi_selector.operations.factory_prototype.classical_factory_prototype import OperationFactoryPrototype
from taf.ul.kpi_selector.operations.rf_lock.classical_rf_lock.rf_lock_prototype import RfLock


class RfLockFactory(OperationFactoryPrototype):
    def __init__(self):
        super(RfLockFactory, self).__init__()

    def get_kpi(self):
        """
        Gets kpi for RF lock operation.
        :return: dictionary with timeout, requirement and operation description for RF lock
        :rtype: dict
        """
        return RfLock(self.bts).get_kpi()
